def transform(grid):
    g=[r[:] for r in grid]
    h,w=len(g),len(g[0])
    # Horizontal bars with a single zero gap; fill gap by matching neighboring color,
    # then extend vertical from gap up through rows above the bar.
    for r in range(h):
        nz=[c for c,v in enumerate(g[r]) if v]
        if len(nz)>=2:
            # each zero internal to same-colored horizontal segment is filled
            for c in range(nz[0],nz[-1]+1):
                if g[r][c]==0:
                    left=next((g[r][x] for x in range(c-1,-1,-1) if g[r][x]),0)
                    right=next((g[r][x] for x in range(c+1,w) if g[r][x]),0)
                    if left==right: g[r][c]=left
            # find internal gap now healed location, extend bar color upward
            for c in range(1,w-1):
                if grid[r][c]==0 and grid[r][c-1] and grid[r][c+1] and grid[r][c-1]==grid[r][c+1]:
                    for rr in range(r): g[rr][c]=grid[r][c-1]
    return g
